public class HashTableChaining {
    static class Node {
        String key; int val;
        Node(String k, int v) { key = k; val = v; }
    }
    private LinkedList<Node>[] table;
    private int capacity;

    public HashTableChaining(int cap) {
        capacity = cap;
        table = new LinkedList[cap];
        for (int i = 0; i < cap; i++) table[i] = new LinkedList<>();
    }

    public void put(String key, int val) {
        int idx = Math.abs(key.hashCode()) % capacity;
        for (Node node : table[idx]) {
            if (node.key.equals(key)) { node.val = val; return; }
        }
        table[idx].add(new Node(key, val));
    }
}

