def longestConsecutive(nums: list[int]) -> int:
    num_set = set(nums)
    max_len = 0

    for num in num_set:
        if (num - 1) not in num_set:
            curr_num = num
            curr_len = 1
            while (curr_num + 1) in num_set:
                curr_num += 1
                curr_len += 1
            max_len = max(max_len, curr_len)

    return max_len

