int longestConsecutive(std::vector<int>& nums) {
    std::unordered_set<int> numSet(nums.begin(), nums.end());
    int maxLen = 0;
    for (int num : numSet) {
        if (!numSet.count(num - 1)) {
            int currNum = num;
            int currLen = 1;
            while (numSet.count(currNum + 1)) {
                currNum++;
                currLen++;
            }
            maxLen = std::max(maxLen, currLen);
        }
    }
    return maxLen;
}

